def restart_schedule(durations, dependencies, bays):
    device_count = len(durations)
    prerequisites = []
    schedule = []
    for device in range(device_count):
        prerequisites.append([])
        schedule.append([])
    for dependency in dependencies:
        prerequisites[dependency[1]].append(dependency[0])
    minute = 0
    started = 0
    last_finish = 0
    while started < device_count:
        free_bays = bays
        for shift in schedule:
            if len(shift) > 0 and shift[1] > minute:
                free_bays -= 1
        for device in range(device_count):
            if free_bays == 0:
                break
            if len(schedule[device]) > 0:
                continue
            ready = True
            for required in prerequisites[device]:
                shift = schedule[required]
                if len(shift) == 0 or shift[1] > minute:
                    ready = False
                    break
            if ready:
                finish = minute + durations[device]
                schedule[device] = [minute, finish]
                if finish > last_finish:
                    last_finish = finish
                started += 1
                free_bays -= 1
        if started == device_count:
            return [last_finish, schedule]
        next_finish = None
        for shift in schedule:
            if len(shift) > 0 and shift[1] > minute:
                if next_finish is None or shift[1] < next_finish:
                    next_finish = shift[1]
        if next_finish is None:
            return None
        minute = next_finish
    return [last_finish, schedule]

